// -- 20. TRINITY COMMANDS --
test("saveOS TRINITY: status command returns complete state", async () => {
  const toolMod = await import("../src/lib/trinity-tool.js?t=" + Date.now())
  if (typeof toolMod.execute === "function") {
    const statusResult = await toolMod.execute({}, { action: "status" })
    if (statusResult) {
      assert.ok(statusResult.includes("vibeOS") || statusResult.includes("brain") || statusResult.includes("slot"))
    }
  }
})

test("saveOS TRINITY: slot switching changes model tier", async () => {
  const toolMod = await import("../src/lib/trinity-tool.js?t=" + Date.now())
  if (typeof toolMod.execute === "function") {
    await toolMod.execute({}, { action: "set", slot: "brain" })
    const tiers = JSON.parse(readFileSync(join(sandbox, ".claude/model-tiers.json"), "utf-8"))
    assert.equal(tiers.selection.active_slot, "brain", "slot switches to brain")
  }
})

test("saveOS ENFORCEMENT: enforce on is mandatory and off is refused", async () => {
  const toolMod = await import("../src/lib/trinity-tool.js?t=" + Date.now())
  if (typeof toolMod.execute === "function") {
    const refuse = await toolMod.execute({}, { action: "enforce", slot: "off" })
    const tiers = JSON.parse(readFileSync(join(sandbox, ".claude/model-tiers.json"), "utf-8"))
    assert.ok(refuse.includes("mandatory") || refuse.includes("cannot be disabled"), "off is refused: " + refuse)
    assert.equal(tiers.selection.delegation_enforce, true, "enforcement stays enabled")
    await toolMod.execute({}, { action: "enforce", slot: "on" })
    const tiers2 = JSON.parse(readFileSync(join(sandbox, ".claude/model-tiers.json"), "utf-8"))
    assert.equal(tiers2.selection.delegation_enforce, true, "enforcement remains enabled")
  }
})

test("saveOS THINKING: thinking full/brief/off controls", async () => {
  const toolMod = await import("../src/lib/trinity-tool.js?t=" + Date.now())
  if (typeof toolMod.execute === "function") {
    await toolMod.execute({}, { action: "thinking", slot: "full" })
    await toolMod.execute({}, { action: "thinking", slot: "brief" })
    await toolMod.execute({}, { action: "thinking", slot: "off" })
    assert.ok(true, "thinking mode controls cycle without error")
  }
})

test("saveOS DIAGNOSE: trinity diagnose inspects config", async () => {
  const toolMod = await import("../src/lib/trinity-tool.js?t=" + Date.now())
  if (typeof toolMod.execute === "function") {
    const result = await toolMod.execute({}, { action: "diagnose" })
    assert.ok(result, "diagnose produces output")
    assert.ok(result.includes("vibeOS") || result.includes("model") || result.includes("tier") || result.includes("config"))
  }
})

