// -- 22. PRICING --
test("saveOS PRICING: modelCostPerTurn returns numeric cost", async () => {
  process.env.CLAUDE_CREDIT_PERCENT = "200"
  const { mod } = await freshPlugin()
  delete process.env.CLAUDE_CREDIT_PERCENT
  if (typeof mod.modelCostPerTurn === "function") {
    const cost = mod.modelCostPerTurn("deepseek/deepseek-v4-pro")
    assert.equal(typeof cost, "number", "modelCostPerTurn returns numeric cost")
  }
})

// -- 23. COST FORMATTER --
test("saveOS COST: formatCost produces correct USD formatting", async () => {
  const cfMod = await import("../src/utils/cost-formatter.js?" + Date.now())
  if (typeof cfMod.formatCost === "function") {
    assert.ok(cfMod.formatCost(0).includes("0.00") || cfMod.formatCost(0) === "$0.00", "formatCost of 0")
    assert.ok(cfMod.formatCost(0.01).includes("$"), "formatCost includes dollar sign")
  }
})

// -- 24. MATH --
test("saveOS MATH: roundTo rounds to specified decimals", async () => {
  const mathMod = await import("../src/utils/math.js?" + Date.now())
  if (typeof mathMod.roundTo === "function") {
    assert.equal(mathMod.roundTo(1.23456, 2), 1.23)
    assert.equal(mathMod.roundTo(1.235, 2), 1.24)
  }
})

// -- 25. TIMER --
test("saveOS TIMER: sessionDuration returns duration object", async () => {
  const timerMod = await import("../src/utils/timer.js?" + Date.now())
  if (typeof timerMod.sessionDuration === "function") {
    const dur = timerMod.sessionDuration()
    assert.ok(typeof dur === "object", "sessionDuration returns object")
    assert.ok("hours" in dur && "minutes" in dur && "seconds" in dur, "duration has hour/min/sec")
  }
})

test("saveOS TIMER: formatDuration formats seconds", async () => {
  const timerMod = await import("../src/utils/timer.js?" + Date.now())
  if (typeof timerMod.formatDuration === "function") {
    const formatted = timerMod.formatDuration(3661)
    assert.ok(formatted.includes("1h") || formatted.includes("1m") || formatted.includes("1s") || formatted.includes(":"))
  }
})

